// GENERATED by Nebula. Every rebuild replaces this file: do not edit it.
// Put your own helpers in another file and import from this one.

// Server-only helpers for Nebula sandbox proxy endpoints.
//
// Use these from Next.js Route Handlers (`src/app/api/<name>/route.ts`) and
// Server Actions. They are server-only, so importing them into a Client
// Component will throw at runtime. Browsers must call your own `/api/...`
// route, which then calls these helpers.
//
// The auth token is read PER CALL (see `sandboxAuthToken`), never captured at
// import time: it is rotated roughly hourly underneath a running process, and
// a captured copy stops working an hour after the app starts.
//
// Why this exists: miniapps run in an untrusted sandbox and must NEVER ship
// third-party API keys or tokens. The Nebula backend injects the right
// credentials server-side. Use these helpers any time the miniapp needs
// dynamic data from a user-connected service (GitHub repos, Gmail threads,
// Linear issues, etc.) - hard-coding that data is what you would do without
// the proxy. With the proxy, fetch it at request time. For named Nebula tools
// such as GMAIL_FETCH_EMAILS, use callTool from a server route; do not have the
// agent call the tool in chat and paste/cache the result into source files. If
// the tool lives on a helper agent, pass that helper slug as callTool({ agentSlug }).
// That helper slug is not permission to use a chat-side agent turn or the message proxy to
// fetch data into files; the miniapp route itself must keep calling callTool.
// If a proxy request fails, return a visible error and fix the route/env/account
// wiring; do not add a cache fallback for live user data.

export type ConnectedAccount = { account_id: string; display_name: string };

export type ConnectedApp = {
  base_url?: string;
  headers?: Record<string, string>;
  accounts: ConnectedAccount[];
};

export type ConnectedApps = Record<string, ConnectedApp>;

export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

export type ConnectedAppCallArgs = {
  app: string;
  method?: HttpMethod;
  url: string;
  // Omit in a route that serves visitors: the proxy then uses the VISITOR's own
  // account for the app. Set it only to an account the visitor picked.
  accountId?: string;
  body?: unknown;
  headers?: Record<string, string>;
  params?: Record<string, unknown>;
};

export type ProxyResponse<T = unknown> = {
  success: boolean;
  data?: T;
  error?: string;
  /** HTTP status of a refused call (for example 403); absent on success. */
  status?: number;
  /**
   * True when the person viewing the miniapp has not connected the app this
   * call needs. Render `error` as a "connect it in Nebula" prompt, not a failure.
   */
  needsConnection?: boolean;
};

export type AgentMessageArgs = {
  content: string;
  threadId?: string;
};

export type AgentMessageResponse = {
  thread_id: string;
  message_id: string;
  status: "queued" | "cleared";
};

export type NebulaApiArgs = {
  // Path under /internal/proxy/nebula, e.g. "me", "workspace", "agents", or `agents/${id}`.
  path: string;
  method?: HttpMethod;
  body?: unknown;
  // Query params; null/undefined values are dropped.
  params?: Record<string, unknown>;
};

export type ToolCallArgs = {
  toolName: string;
  arguments?: Record<string, unknown>;
  // Defaults to AGENT_SLUG when omitted.
  agentSlug?: string;
  // Omit to create a new miniapp-sourced thread for this call.
  threadId?: string;
};

export type ToolCallResponse<T = unknown> = {
  success: boolean;
  tool_name: string;
  thread_id: string;
  message_id: string;
  // Full tool result envelope. Connected-app actions wrap their payload as
  // { success, message, exports, ... }; built-in tools return their own shape.
  result?: unknown;
  // The tool's data payload: `result.exports` when the envelope wraps one,
  // otherwise `result` itself. Read your data from here.
  data?: T;
  error?: string;
};

export type ToolDefinition = {
  name: string;
  description: string;
  parameters_json_schema: Record<string, unknown>;
};

export type ToolListResponse = {
  agent_slug: string;
  thread_id: string;
  tools: ToolDefinition[];
};

function assertServer(): void {
  if (typeof window !== "undefined") {
    throw new Error(
      "nebula-proxy helpers are server-only. Call them from a Next.js Route Handler or Server Action, never from a Client Component.",
    );
  }
}

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing env var ${name}. The Nebula runtime sets it on every miniapp; do not run this outside the sandbox.`);
  }
  return value;
}

// `process.env.SANDBOX_AUTH_TOKEN` is a SNAPSHOT taken when this service was
// exec'd, and the token behind it lives one hour. The sandbox's refresh loop
// rewrites `~/.nebula-env` every 30 minutes but deliberately does not restart
// your process, so a long-running miniapp holds a dead token in `process.env`
// while a valid one sits on disk - and every proxy call 401s forever.
// So: read the file at call time, and fall back to the environment only when
// the file is unreadable (outside the sandbox, or before the first refresh).
const NEBULA_ENV_FILE = ".nebula-env";

async function tokenFromEnvFile(): Promise<string | undefined> {
  try {
    const [{ readFile }, { homedir }, { join }] = await Promise.all([
      import("node:fs/promises"),
      import("node:os"),
      import("node:path"),
    ]);
    const contents = await readFile(join(homedir(), NEBULA_ENV_FILE), "utf8");
    // Lines look like `export SANDBOX_AUTH_TOKEN='<jwt>'`; the refresher rewrites
    // the file wholesale, so the LAST occurrence is the live one.
    const matches = contents.match(/^\s*(?:export\s+)?SANDBOX_AUTH_TOKEN=.*$/gm);
    const last = matches?.at(-1);
    return last?.split("=").slice(1).join("=").trim().replace(/^["']|["']$/g, "") || undefined;
  } catch {
    return undefined;
  }
}

/**
 * The sandbox's CURRENT auth token. Always call this per request - never hoist
 * the result into a module-level constant, which reintroduces the stale-token
 * bug this function exists to fix.
 */
export async function sandboxAuthToken(): Promise<string> {
  assertServer();
  return (await tokenFromEnvFile()) ?? requireEnv("SANDBOX_AUTH_TOKEN");
}

// The visitor whose request this server code is serving. The Nebula edge
// stamps every request it lets through with `x-nebula-caller`, and forwarding
// it makes the proxy act as THAT person - their connected accounts, their
// usage - instead of whoever owns this sandbox. It is also the call's whole
// credential: with it, a missing or expired sandbox token does not matter.
// It is read from the incoming request each call and forwarded only here:
// never log it, store it, or send it to the browser. Outside a request (a
// cron, a background job) there is none, and the proxy acts as the sandbox's
// own token.
async function callerToken(): Promise<string | undefined> {
  try {
    const { headers } = await import("next/headers");
    return (await headers()).get("x-nebula-caller") ?? undefined;
  } catch {
    return undefined;
  }
}

/**
 * `fetch` against a Nebula proxy endpoint with the sandbox token attached.
 *
 * Retries ONCE on a 401 with a freshly re-read token: a token can expire
 * mid-request, and that retry is what turns a permanent wedge into a blip.
 * Use this for every proxy call rather than hand-rolling the header.
 */
export async function proxyFetch(
  input: RequestInfo | URL,
  init: RequestInit = {},
): Promise<Response> {
  assertServer();
  // Signature matches the SDKs' `fetch` option exactly. Narrowing `input` to
  // `string` would fail `next build` under strictFunctionTypes, which checks a
  // function-typed property's parameters contravariantly.
  const caller = await callerToken();
  const send = async (token: string | undefined): Promise<Response> => {
    // `new Headers(...)`, never a spread: an SDK passes a `Headers` instance,
    // and spreading one yields `{}` - silently dropping Content-Type,
    // anthropic-version and every x-stainless-* header the request needs.
    const headers = new Headers(init.headers);
    if (token) {
      headers.set("Authorization", `Bearer ${token}`);
    }
    if (caller) {
      headers.set("X-Nebula-Caller", caller);
    }
    return fetch(input, { ...init, headers });
  };

  // A visitor's request is authorized by its caller token, so it must not
  // fail on a sandbox token this box could not refresh.
  const token = caller
    ? ((await tokenFromEnvFile()) ?? process.env.SANDBOX_AUTH_TOKEN)
    : await sandboxAuthToken();
  const resp = await send(token);
  if (resp.status !== 401) {
    return resp;
  }
  const refreshed = await tokenFromEnvFile();
  return refreshed && refreshed !== token ? send(refreshed) : resp;
}

/** Parse $CONNECTED_APPS into a typed map. */
export function listConnectedApps(): ConnectedApps {
  assertServer();
  const raw = process.env.CONNECTED_APPS;
  if (!raw) return {};
  try {
    return JSON.parse(raw) as ConnectedApps;
  } catch {
    return {};
  }
}

/**
 * Pick one of the DEPLOYER's connected accounts for `app` from $CONNECTED_APPS.
 * A visitor cannot spend these, so do not use this in a route that serves
 * visitors; omit `accountId` from `callAppProxy` there instead. Defaults to
 * the first account when `preferredAccountId` is omitted; returns `null` when the app is not
 * connected. Use the return value's `account_id` as the `accountId` arg to
 * `callAppProxy`.
 */
export function pickConnectedAccount(app: string, preferredAccountId?: string): ConnectedAccount | null {
  const apps = listConnectedApps();
  const entry = apps[app];
  if (!entry || entry.accounts.length === 0) return null;
  if (preferredAccountId) {
    const match = entry.accounts.find((a) => a.account_id === preferredAccountId);
    if (match) return match;
  }
  return entry.accounts[0];
}

function queryString(params?: Record<string, unknown>): string {
  if (!params) return "";
  const query = new URLSearchParams(
    Object.entries(params).flatMap(([key, value]) =>
      value == null ? [] : ([[key, String(value)]] as [string, string][]),
    ),
  ).toString();
  return query ? `?${query}` : "";
}

/**
 * Call a raw user-connected app/custom-API HTTP endpoint via
 * `POST /internal/proxy/app`. Tokens and API keys never leave the backend.
 * Without `accountId`, the proxy uses the visitor's own account for `app`, else
 * one the workspace shares. When there is neither, the result has
 * `needsConnection: true` and `error` says which app the visitor must connect.
 * Prefer callTool for named Nebula tool actions such as GMAIL_FETCH_EMAILS.
 * Gmail inbox/email dashboards must use callTool("GMAIL_FETCH_EMAILS"), not
 * callAppProxy or raw Gmail REST URLs.
 */
export async function callAppProxy<T = unknown>(args: ConnectedAppCallArgs): Promise<ProxyResponse<T>> {
  assertServer();
  const proxyUrl = requireEnv("NEBULA_PROXY_URL");
  const resp = await proxyFetch(`${proxyUrl}/internal/proxy/app`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      app: args.app,
      method: args.method ?? "GET",
      url: args.url,
      ...(args.accountId ? { account_id: args.accountId } : {}),
      body: args.body,
      headers: args.headers,
      params: args.params,
    }),
  });
  const body: unknown = await resp.json().catch(() => null);
  if (resp.ok) return body as ProxyResponse<T>;
  return proxyRefusal<T>(resp.status, body);
}

/**
 * Keep the backend's reason for a refused proxy call. A refusal answers with
 * `{ detail }`, not a ProxyResponse, so reading it as one lost the message and
 * the miniapp could only say "Request failed".
 */
function proxyRefusal<T>(status: number, body: unknown): ProxyResponse<T> {
  const detail = (body as { detail?: unknown } | null)?.detail;
  const fallback = `Request failed (${status})`;
  if (detail && typeof detail === "object") {
    const { error, message } = detail as { error?: string; message?: string };
    return { success: false, status, error: message ?? error ?? fallback, needsConnection: error === "app_not_connected" };
  }
  return { success: false, status, error: typeof detail === "string" ? detail : fallback };
}

/**
 * Base URL + bearer token for the Nebula LLM proxy. Use as the
 * `baseURL` / `apiKey` of the OpenAI or Anthropic SDK client; the user's
 * selected model is used regardless of the `model` field you pass.
 *
 * Build the client INSIDE the request handler and pass `fetch: proxyFetch`.
 * An SDK client captures `apiKey` when it is constructed, so a client built
 * once at module scope pins a token that dies an hour later and 401s for the
 * rest of the process's life; `proxyFetch` re-reads and retries instead.
 *
 * ```ts
 * export async function POST(request: Request) {
 *   const client = new OpenAI({
 *     baseURL: `${llmProxyBaseUrl()}/v1`,
 *     apiKey: await sandboxAuthToken(),
 *     fetch: proxyFetch,
 *   });
 *   ...
 * }
 * ```
 */
export function llmProxyBaseUrl(): string {
  assertServer();
  return `${requireEnv("NEBULA_PROXY_URL")}/internal/proxy/llm`;
}

/**
 * Send a message back to the calling agent via
 * `POST /internal/proxy/messages`. Use for "run this report" / "ping me when
 * X" buttons. Omit `threadId` to start a fresh thread bound to the agent.
 *
 * Do NOT create a webhook trigger for in-miniapp callbacks; that is for
 * external services calling Nebula.
 */
export async function postAgentMessage(args: AgentMessageArgs): Promise<AgentMessageResponse> {
  assertServer();
  const proxyUrl = requireEnv("NEBULA_PROXY_URL");
  const agentSlug = requireEnv("AGENT_SLUG");
  const resp = await proxyFetch(`${proxyUrl}/internal/proxy/messages`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      agent_slug: agentSlug,
      content: args.content,
      ...(args.threadId ? { thread_id: args.threadId } : {}),
    }),
  });
  if (!resp.ok) {
    throw new Error(`Nebula message proxy failed (${resp.status}): ${await resp.text()}`);
  }
  return (await resp.json()) as AgentMessageResponse;
}

/**
 * Read first-party Nebula resources scoped to the sandbox token's user and
 * workspace. Supported paths include `me`, `workspace`, `agents`,
 * `agents/<id-or-slug>`, `channels` and `channels/<id-or-slug>/messages`
 * (attributed, newest first). This is read-only; use `postAgentMessage` or
 * `callTool` for actions.
 */
export async function callNebulaApi<T = unknown>(args: NebulaApiArgs): Promise<T> {
  assertServer();
  const proxyUrl = requireEnv("NEBULA_PROXY_URL");
  let path = args.path;
  while (path.startsWith("/")) {
    path = path.slice(1);
  }
  const resp = await proxyFetch(`${proxyUrl}/internal/proxy/nebula/${path}${queryString(args.params)}`, {
    method: args.method ?? "GET",
    headers: {
      "Content-Type": "application/json",
    },
    ...(args.body !== undefined ? { body: JSON.stringify(args.body) } : {}),
  });
  if (!resp.ok) {
    throw new Error(`Nebula API ${path} failed (${resp.status}): ${await resp.text()}`);
  }
  return (await resp.json()) as T;
}

/**
 * Execute one tool through the agent's scoped Nebula tool surface. This covers
 * built-in tools plus dynamically loaded connected-app/custom-toolkit tools.
 * Use this for named actions such as GMAIL_FETCH_EMAILS from a Next.js API
 * route, so the miniapp fetches live data at request time instead of receiving
 * a stale cache produced by an agent-side tool call. Read the payload from
 * `data` (e.g. `data.messages` for GMAIL_FETCH_EMAILS) - it unwraps the
 * connected-app result envelope for you. Do not mask proxy failures by importing cache JSON;
 * a live-data miniapp should fail visibly until the proxy route is fixed. If a
 * Gmail-capable helper agent owns the tool, pass its slug as args.agentSlug. If a
 * Gmail inbox/email dashboard's callTool route returns 2xx JSON, keep that
 * route and finish; do not replace it with diagnostics, chat-side agent output,
 * direct NEBULA_PROXY_URL probes, or raw Gmail HTTP, and do not inspect
 * env vars, supervisor state, or logs after that success.
 */
export async function callTool<T = unknown>(args: ToolCallArgs): Promise<ToolCallResponse<T>> {
  assertServer();
  const proxyUrl = requireEnv("NEBULA_PROXY_URL");
  const resp = await proxyFetch(`${proxyUrl}/internal/proxy/tools`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      agent_slug: args.agentSlug ?? requireEnv("AGENT_SLUG"),
      tool_name: args.toolName,
      arguments: args.arguments ?? {},
      ...(args.threadId ? { thread_id: args.threadId } : {}),
    }),
  });
  if (!resp.ok) {
    throw new Error(`Nebula tool proxy failed (${resp.status}): ${await resp.text()}`);
  }
  const payload = (await resp.json()) as ToolCallResponse<T>;
  // Connected-app actions wrap their payload in a { success, message, exports }
  // envelope; built-in tools return their result directly.
  const result = payload.result;
  payload.data = (
    result && typeof result === "object" && "exports" in result
      ? (result as { exports: unknown }).exports
      : result
  ) as T;
  return payload;
}

/**
 * List tool schemas visible to an agent in an existing single-agent thread.
 * This is read-only and does not create a thread.
 */
export async function listTools(args: { agentSlug?: string; threadId: string }): Promise<ToolListResponse> {
  assertServer();
  const proxyUrl = requireEnv("NEBULA_PROXY_URL");
  const resp = await proxyFetch(
    `${proxyUrl}/internal/proxy/tools${queryString({
      agent_slug: args.agentSlug ?? requireEnv("AGENT_SLUG"),
      thread_id: args.threadId,
    })}`,
    { method: "GET" },
  );
  if (!resp.ok) {
    throw new Error(`Nebula tool list failed (${resp.status}): ${await resp.text()}`);
  }
  return (await resp.json()) as ToolListResponse;
}

